<template><ion-page><ion-content class="publico"><main><a href="/catalogo">← Catálogo</a><section v-if="cargando">Cargando registro público…</section><section v-else-if="error"><h1>Registro no disponible</h1><p>{{ error }}</p></section><article v-else-if="pedido"><img v-if="url_imagen_lote(pedido.lote.imagen_avatar)" :src="url_imagen_lote(pedido.lote.imagen_avatar) ?? undefined" :alt="`Imagen del lote ${pedido.lote.nombre}`"><small>REGISTRO PÚBLICO SYNER</small><h1>{{ pedido.lote.nombre }}</h1><span class="estado">{{ pedido.estado }}</span><p>{{ pedido.lote.categoria }} · {{ pedido.lote.proveedor }} <b v-if="pedido.lote.proveedor_verificado">✓ Verificado</b></p><div class="precio">{{ moneda(pedido.lote.precio_cupo) }} <small>precio de cupo</small></div><p>Precio de mercado: {{ moneda(pedido.lote.precio_mercado) }} · Ahorro {{ pedido.lote.porcentaje_ahorro }}%</p><small>Esta página no expone datos personales del solicitante.</small></article></main></ion-content></ion-page></template>
<script setup lang="ts">
import { onMounted, ref, watch } from "vue"; import { useRoute } from "vue-router"; import { IonContent,IonPage } from "@ionic/vue"; import { obtener } from "@/services/ajax_service"; import { url_imagen_lote } from "@/services/lotes_service";
interface PedidoPublico { estado:string; lote:{nombre:string;categoria:string;imagen_avatar?:string|null;precio_cupo:number;precio_mercado:number;porcentaje_ahorro:number;proveedor:string;proveedor_verificado:boolean} }
const route=useRoute(), pedido=ref<PedidoPublico|null>(null), cargando=ref(true), error=ref(""); const moneda=(n:number)=>new Intl.NumberFormat("es-AR",{style:"currency",currency:"ARS",maximumFractionDigits:0}).format(n);
async function cargar(){cargando.value=true;error.value="";try{pedido.value=await obtener<PedidoPublico>(`publico/pedidos/${encodeURIComponent(String(route.params.token))}`)}catch{pedido.value=null;error.value="El enlace puede haber vencido o no existir."}finally{cargando.value=false}}
onMounted(cargar); watch(()=>route.params.token,cargar);
</script>
<style scoped>.publico{--background:#f4f7fb;color:#172033}.publico main{max-width:700px;margin:auto;padding:28px 20px}.publico a{display:inline-block;margin-bottom:20px;color:#2469bd}.publico article,.publico section{padding:26px;border-radius:24px;background:white;box-shadow:0 12px 32px #15335a13}.publico article img{display:block;width:calc(100% + 52px);height:220px;margin:-26px -26px 20px;object-fit:cover;border-radius:24px 24px 0 0;background:#e9eef5}.publico h1{font-size:32px}.publico .estado{display:inline-block;padding:8px 12px;border-radius:30px;background:#e7f4ef;color:#147854;text-transform:capitalize}.publico .precio{font-size:30px;font-weight:800}.publico .precio small{display:block;font-size:13px;font-weight:400}.publico article>small{color:#66758c}.publico b{color:#12845b}</style>
